  fn write_u8(&mut self, _i: u8) {}
  #[inline]
  fn write_usize(&mut self, i: usize) { self.hash = (self.hash.rotate_left(5) ^ i as u64).wrapping_mul(0x51_7c_c1_b7_27_22_0a_95); }
  #[inline]
  fn finish(&self) -> u64 { self.hash ^ (self.hash >> 29) }
