/// a local: a shared cell, so that a lambda can take it (a clone of the cell) and write it. A method makes a cell
/// for every local it binds, so they come off a free list of the thread's own rather than the allocator.
pub struct Local(std::ptr::NonNull<LocalBox>);
struct LocalBox { rc: StdCell<usize>, v: std::cell::UnsafeCell<Value> }
thread_local! { static SPARE: RefCell<Vec<std::ptr::NonNull<LocalBox>>> = const { RefCell::new(Vec::new()) }; }
impl Local {
  fn new(v: Value) -> Local {
    let spare = SPARE.with(|s| s.borrow_mut().pop());
    match spare {
      Some(p) => { unsafe { let b = p.as_ref(); b.rc.set(1); std::ptr::write(b.v.get(), v); } Local(p) }
      None => Local(std::ptr::NonNull::from(Box::leak(Box::new(LocalBox { rc: StdCell::new(1), v: std::cell::UnsafeCell::new(v) })))),
    }
  }
  #[inline] fn b(&self) -> &LocalBox { unsafe { self.0.as_ref() } }
}
impl Clone for Local { #[inline] fn clone(&self) -> Local { let b = self.b(); b.rc.set(b.rc.get() + 1); Local(self.0) } }
impl Drop for Local {
  fn drop(&mut self) {
    let b = self.b();
    let n = b.rc.get() - 1;
    b.rc.set(n);
    if n > 0 { return; }
    /* the value is dropped first (it may hold other cells), then the cell is kept for the next local */
    let v = unsafe { std::ptr::read(b.v.get()) };
    drop(v);
    let p = self.0;
    let kept = SPARE.try_with(|s| { let mut s = s.borrow_mut(); if s.len() < 1 << 16 { s.push(p); true } else { false } }).unwrap_or(false);
    if !kept { unsafe { drop(Box::from_raw(p.as_ptr())); } }
  }
}
