pub struct Cls {
  pub name: String,
  pub parent: Option<Rc<Cls>>,
  fields: Map<&'static str, Option<Default>>,
  order: Vec<&'static str>,
  methods: Map<&'static str, Member>,
  getters: Map<&'static str, Member>,
  statics: Map<&'static str, Member>,
  static_defaults: Map<&'static str, Default>,
  static_order: Vec<&'static str>,
  static_slots: RefCell<Map<String, Value>>,
  /// what a name is on this class, once looked up the chain: the class that decides it, and what it is there
  resolved: RefCell<Map<String, Found>>,
}
#[derive(Clone)]
enum Found { Getter(Member), Field(Option<Default>), Method(Member), Nothing }

impl Cls {
  fn new(name: &str, parent: Option<Rc<Cls>>) -> Cls {
    Cls { name: name.to_string(), parent, fields: Map::default(), order: Vec::new(), methods: Map::default(), getters: Map::default(), statics: Map::default(),
      static_defaults: Map::default(), static_order: Vec::new(), static_slots: RefCell::new(Map::default()), resolved: RefCell::new(Map::default()) }
  }
  pub fn field(&mut self, n: &'static str, d: impl Fn(&Value) -> Value + 'static) { self.fields.insert(n, Some(Rc::new(d))); self.order.push(n); }
  pub fn field_none(&mut self, n: &'static str) { self.fields.insert(n, None); self.order.push(n); }
  pub fn method(&mut self, n: &'static str, m: impl Fn(&Value, &[&Value]) -> Value + 'static) { self.methods.insert(n, Rc::new(m)); }
  pub fn getter(&mut self, n: &'static str, m: impl Fn(&Value, &[&Value]) -> Value + 'static) { self.getters.insert(n, Rc::new(m)); }
  pub fn statik(&mut self, n: &'static str, m: impl Fn(&Value, &[&Value]) -> Value + 'static) { self.statics.insert(n, Rc::new(m)); }
  pub fn static_field(&mut self, n: &'static str, d: impl Fn(&Value) -> Value + 'static) {
    if self.static_defaults.insert(n, Rc::new(d)).is_none() { self.static_order.push(n); }
  }
  pub fn is_a(&self, c: &Cls) -> bool { let mut k = Some(self); while let Some(x) = k { if std::ptr::eq(x, c) { return true; } k = x.parent.as_deref(); } false }
  fn chain(&self) -> impl Iterator<Item = &Cls> { let mut k = Some(self); std::iter::from_fn(move || { let x = k?; k = x.parent.as_deref(); Some(x) }) }
  fn find_method(&self, n: &str) -> Option<&Member> { self.chain().find_map(|k| k.methods.get(n)) }
  fn find_static(&self, n: &str) -> Option<&Member> { self.chain().find_map(|k| k.statics.get(n)) }
  fn find_static_field(&self, n: &str) -> Option<&Cls> { self.chain().find(|k| k.static_defaults.contains_key(n) || k.static_slots.borrow().contains_key(n)) }
  /// the nearest class up the chain with a member of this name decides what it is - as a prototype chain does
  fn resolve(&self, n: &str) -> Found {
    if let Some(f) = self.resolved.borrow().get(n) { return f.clone(); }
    let mut found = Found::Nothing;
    for k in self.chain() {
      if let Some(g) = k.getters.get(n) { found = Found::Getter(g.clone()); break; }
      if let Some(d) = k.fields.get(n) { found = Found::Field(d.clone()); break; }
      if let Some(m) = k.methods.get(n) { found = Found::Method(m.clone()); break; }
    }
    self.resolved.borrow_mut().insert(n.to_string(), found.clone());
    found
  }
}

pub struct Obj {
  pub cls: Rc<Cls>,
  pub slots: RefCell<Map<Box<str>, Value>>,
}

// --- the registry: every class, theory and top-level definition, once per thread ------------------------------
struct Registry {
  classes: RefCell<Map<String, Rc<Cls>>>,
  theories: RefCell<Map<String, Value>>,
  constants: RefCell<Map<String, Default>>,
  made: RefCell<Map<String, Value>>,
  loaded: StdCell<bool>,
  node: Rc<Cls>,
}
thread_local! {
  static REG: Registry = {
    let node = Rc::new(Cls::new("Node", None));
    let classes = RefCell::new(Map::default());
    classes.borrow_mut().insert("Node".to_string(), node.clone());
    Registry { classes, theories: RefCell::new(Map::default()), constants: RefCell::new(Map::default()), made: RefCell::new(Map::default()), loaded: StdCell::new(false), node }
  };
}
fn ensure_loaded() {
  let first = REG.with(|r| if r.loaded.get() { false } else { r.loaded.set(true); true });
  if first { crate::physics::load(); }
}
pub fn node_cls() -> Rc<Cls> { REG.with(|r| r.node.clone()) }
fn class_named(n: &str) -> Option<Rc<Cls>> { REG.with(|r| r.classes.borrow().get(n).cloned()) }

/// a class: its parent by name, its members filled by `define`
pub fn cls(name: &str, parent: &str, define: impl FnOnce(&mut Cls)) {
  let p = class_named(parent.rsplit('.').next().unwrap_or(parent)).unwrap_or_else(|| panic!("no class {} to extend", parent));
  let mut c = Cls::new(name, Some(p));
  define(&mut c);
  let c = Rc::new(c);
  REG.with(|r| r.classes.borrow_mut().insert(name.to_string(), c));
}
/// a class by its name (`Boundary.Terminal` by its own), or a theory by its: what a class written in Ray is, as a value
pub fn K(name: &str) -> Value {
  let n = name.rsplit('.').next().unwrap_or(name);
  ensure_loaded();
  if let Some(t) = REG.with(|r| r.theories.borrow().get(n).cloned()) { return t; }
  match class_named(n) { Some(c) => Value::Cls(c), None => panic!("no class {} in this package", name) }
}
/// a top-level definition (`LINE2`), made on first read
pub fn konst(name: &str, f: impl Fn(&Value) -> Value + 'static) { REG.with(|r| r.constants.borrow_mut().insert(name.to_string(), Rc::new(f))); }
pub fn glob(name: &str) -> Value {
  ensure_loaded();
  if let Some(v) = REG.with(|r| r.made.borrow().get(name).cloned()) { return v; }
  let f = REG.with(|r| r.constants.borrow().get(name).cloned()).unwrap_or_else(|| panic!("no definition {} in this package", name));
  REG.with(|r| r.made.borrow_mut().insert(name.to_string(), Null));
  let v = f(&Null);
  REG.with(|r| r.made.borrow_mut().insert(name.to_string(), v.clone()));
  v
}
/// a theory: its class made once, its rules and theorems read off the class in the order they are written
pub fn theory(name: &str) {
  let c = class_named(name).unwrap();
  let o = make_cls(&c, &[]);
  REG.with(|r| r.theories.borrow_mut().insert(name.to_string(), o.clone()));
  let mut chain: Vec<&Cls> = c.chain().collect();
  chain.reverse();
  let cv = Value::Cls(c.clone());
  let (mut rules, mut theorems) = (Vec::new(), Vec::new());
  for k in chain { for n in &k.static_order { if n.starts_with("rule ") { rules.push(get(&cv, n)); } else if n.starts_with("theorem ") { theorems.push(get(&cv, n)); } } }
  set(&o, "rules", &Value::list(rules));
  set(&o, "theorems", &Value::list(theorems));
}

/// `Class(x: 1, ...)`: an object of the class, its named fields set
pub fn make(kind: &str, a: &[&Value]) -> Value {
  match K(kind) { Value::Cls(c) => make_cls(&c, a), _ => panic!("{} is not a class", kind) }
}
pub fn make_k(kind: &Value, a: &[&Value]) -> Value {
  match kind { Value::Cls(c) => make_cls(c, a), _ => panic!("{} is not a class", tos_v(kind)) }
}
pub fn make_cls(c: &Rc<Cls>, a: &[&Value]) -> Value {
  let o = Obj { cls: c.clone(), slots: RefCell::new(Map::default()) };
  {
    let mut slots = o.slots.borrow_mut();
    let mut names: Vec<&'static str> = Vec::new();
    let mut positional = 0;
    let mut chain: Vec<&Cls> = c.chain().collect();
    chain.reverse();
    for k in chain { names.extend(k.order.iter().copied()); }
    for x in a {
      if let Value::Kw(kw) = x { slots.insert(Box::from(&*kw.0), kw.1.clone()); }
      else if positional < names.len() { slots.insert(Box::from(names[positional]), (*x).clone()); positional += 1; }
    }
  }
  Value::Obj(Rc::new(o))
}
/// `{}`: an object with no class of its own - a map
pub fn node() -> Value { make_cls(&node_cls(), &[]) }
pub fn kw<T: CV + ?Sized>(n: &str, v: &T) -> Value { Value::Kw(Rc::new((Rc::from(n), own(v)))) }

// --- members by name ------------------------------------------------------------------------------------------
pub fn get<T: CV + ?Sized>(t: &T, n: &str) -> Value { get_v(&t.cv(), n) }
pub fn get_v(t: &Value, n: &str) -> Value {
  match t {
    Value::Obj(o) => {
      let hit = o.slots.borrow().get(n).cloned();
      if let Some(v) = hit { return v; }
      match o.cls.resolve(n) {
        Found::Getter(g) => g(t, &[]),
        Found::Field(d) => { let v = match d { Some(d) => d(t), None => Null }; o.slots.borrow_mut().insert(Box::from(n), v.clone()); v }
        Found::Method(m) => { let me = t.clone(); Value::Fn(Rc::new(move |a: &[&Value]| m(&me, a))) }
        Found::Nothing => match o.cls.find_static_field(n) { Some(k) => static_of(k, n), None => Null },
      }
    }
    Value::Cls(c) => {
      if let Some(k) = c.find_static_field(n) { return static_of(k, n); }
      if let Some(s) = c.find_static(n) { let s = s.clone(); return s(&Null, &[]); }
      Null
    }
    Value::Many(m) => collapse(m.iter().map(|x| if x.is_null() { Null } else { get_v(x, n) }).collect()),
    Null => panic!("no member {} on None", n),
    _ => { if n == "length" { return len_v(t); } panic!("no member {} on {}", n, kind(t)) }
  }
}
fn static_of(k: &Cls, n: &str) -> Value {
  let had = k.static_slots.borrow().get(n).cloned();
  if let Some(v) = had { return v; }
  let d = k.static_defaults.get(n).unwrap().clone();
  let v = d(&Null);
  k.static_slots.borrow_mut().insert(n.to_string(), v.clone());
  v
}
fn kind(t: &Value) -> &'static str {
  match t { Null => "None", Value::Num(_) => "Number", Value::Bool(_) => "boolean", Value::Str(_) => "String", Value::List(_) => "Array", Value::Obj(_) => "Obj", Value::Fn(_) => "Fn", Value::Cls(_) => "Cls", Value::Many(_) => "Many", Value::Kw(_) => "Kw" }
}
pub fn get_opt<T: CV + ?Sized>(t: &T, n: &str) -> Value { let t = t.cv(); if t.is_null() { Null } else { get_v(&t, n) } }
pub fn set<T: CV + ?Sized, V: CV + ?Sized>(t: &T, n: &str, v: &V) -> Value { let v = own(v); set_v(&t.cv(), n, v.clone()); v }
fn set_v(t: &Value, n: &str, v: Value) {
  match t {
    Value::Obj(o) => { o.slots.borrow_mut().insert(Box::from(n), v); }
    Value::Cls(c) => { let k = c.find_static_field(n).unwrap_or(c); k.static_slots.borrow_mut().insert(n.to_string(), v); }
    Value::Many(m) => { for x in m.iter() { set_v(x, n, v.clone()); } }
    _ => panic!("no member {} to set on {}", n, tos_v(t)),
  }
}
pub fn call<T: CV + ?Sized>(t: &T, n: &str, a: &[&Value]) -> Value { call_v(&t.cv(), n, a) }
pub fn call_v(t: &Value, n: &str, a: &[&Value]) -> Value {
  match t {
    Value::Obj(o) => {
      let own_slot = o.slots.borrow().contains_key(n);
      if !own_slot { if let Found::Method(m) = o.cls.resolve(n) { return m(t, a); } }
      match get_v(t, n) { Value::Fn(f) => f(a), Null => panic!("no method {} on {}", n, o.cls.name), f => f }
    }
    Value::Cls(c) => {
      if let Some(s) = c.find_static(n) { let s = s.clone(); return s(&Null, a); }
      match get_v(t, n) { Value::Fn(f) => f(a), _ => panic!("no static {} on {}", n, c.name) }
    }
    Value::Many(m) => collapse(m.iter().map(|x| call_v(x, n, a)).collect()),
    Null => panic!("no method {} on None", n),
    _ => panic!("no method {} on {}", n, kind(t)),
  }
}
pub fn invoke<T: CV + ?Sized>(f: &T, a: &[&Value]) -> Value {
  match &*f.cv() { Value::Fn(f) => f(a), x => panic!("not a program: {}", tos_v(x)) }
}
pub fn call_opt<T: CV + ?Sized>(t: &T, n: &str, a: &[&Value]) -> Value { let t = t.cv(); if t.is_null() { Null } else { call_v(&t, n, a) } }
pub fn choose<T: CV + ?Sized>(t: &T, name: &str) -> Value { get_v(&t.cv(), &format!("choose {}", name)) }
/// whether an object has a member of this name, of its own or its class's
pub fn has<T: CV + ?Sized>(t: &T, n: &str) -> bool {
  match &*t.cv() {
    Value::Obj(o) => o.slots.borrow().contains_key(n) || !matches!(o.cls.resolve(n), Found::Nothing),
    Value::Cls(c) => c.find_static(n).is_some() || c.find_static_field(n).is_some(),
    _ => false,
  }
}
/// a share of a term: its source, and the program that reads it at the symbols
pub fn at(source: &str, f: impl Fn(&Value) -> Value + 'static) -> Value {
  let o = node();
  set(&o, "source", source);
  set(&o, "at", &fnv(move |a: &[&Value]| f(&arg(a, 0))));
  o
}
pub fn instance_of<T: CV + ?Sized>(x: &T, c: &str) -> bool {
  let x = x.cv();
  match c {
    "N" | "Natural" | "Z" | "Integer" | "Real" | "Decimal" | "Number" => return matches!(&*x, Value::Num(_)),
    "String" => return matches!(&*x, Value::Str(_)),
    "boolean" => return matches!(&*x, Value::Bool(_)),
    "Array" => return matches!(&*x, Value::List(_)),
    _ => {}
  }
  match (&*x, K(c)) { (Value::Obj(o), Value::Cls(k)) => o.cls.is_a(&k), _ => false }
}
pub fn is_list<T: CV + ?Sized>(x: &T) -> bool { matches!(&*x.cv(), Value::List(_)) }

// --- what the language's operators are here -------------------------------------------------------------------
pub fn truthy<T: CV + ?Sized>(x: &T) -> bool { truthy_v(&x.cv()) }
pub fn truthy_v(x: &Value) -> bool {
  match x { Null => false, Value::Bool(b) => *b, Value::Num(d) => *d != 0.0 && !d.is_nan(), Value::Str(s) => !s.is_empty(), _ => true }
}
pub fn num<T: CV + ?Sized>(x: &T) -> f64 { num_v(&x.cv()) }
pub fn num_v(x: &Value) -> f64 { match x { Null => 0.0, Value::Num(d) => *d, Value::Bool(b) => if *b { 1.0 } else { 0.0 }, _ => f64::NAN } }
#[inline] fn arith(a: &Value) -> bool { matches!(a, Null | Value::Num(_) | Value::Bool(_)) }
pub fn eq<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> bool { eq_v(&a.cv(), &b.cv()) }
pub fn eq_v(a: &Value, b: &Value) -> bool {
  match (a, b) {
    (Null, Null) => true,
    (Null, _) | (_, Null) => false,
    (Value::Many(m), _) => m.iter().all(|x| eq_v(x, b)),
    (Value::Num(x), Value::Num(y)) => x == y,
    (Value::Str(x), Value::Str(y)) => x == y,
    (Value::Bool(x), Value::Bool(y)) => x == y,
    (Value::List(x), Value::List(y)) => {
      if Rc::ptr_eq(x, y) { return true; }
      let (x, y) = (x.borrow().clone(), y.borrow().clone());
      x.len() == y.len() && x.iter().zip(y.iter()).all(|(p, q)| eq_v(p, q))
    }
    (Value::Obj(x), _) => {
      if let Value::Obj(y) = b { if Rc::ptr_eq(x, y) { return true; } }
      if x.cls.find_method("equals").is_some() { truthy_v(&call_v(a, "equals", &[b])) } else { false }
    }
    (Value::Fn(x), Value::Fn(y)) => Rc::ptr_eq(x, y),
    (Value::Cls(x), Value::Cls(y)) => Rc::ptr_eq(x, y),
    _ => false,
  }
}
/// the same thing (not only an equal one): what a superposition collapses on
fn same(a: &Value, b: &Value) -> bool {
  match (a, b) {
    (Null, Null) => true,
    (Value::Num(x), Value::Num(y)) => x == y,
    (Value::Bool(x), Value::Bool(y)) => x == y,
    (Value::Str(x), Value::Str(y)) => x == y,
    (Value::List(x), Value::List(y)) => Rc::ptr_eq(x, y) || eq_v(a, b),
    (Value::Obj(x), Value::Obj(y)) => Rc::ptr_eq(x, y),
    (Value::Fn(x), Value::Fn(y)) => Rc::ptr_eq(x, y),
    (Value::Cls(x), Value::Cls(y)) => Rc::ptr_eq(x, y),
    (Value::Many(x), Value::Many(y)) => Rc::ptr_eq(x, y),
    _ => false,
  }
}
fn cmp_str(a: &Value, b: &Value) -> Option<std::cmp::Ordering> {
  match (a, b) { (Value::Str(x), Value::Str(y)) => Some(x.cmp(y)), (Value::Str(x), y) => Some((**x).cmp(&*tos_v(y))), _ => None }
}
pub fn lt<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Bool(num_v(&a) < num_v(&b)) } else if let Some(o) = cmp_str(&a, &b) { Value::Bool(o.is_lt()) } else { call_v(&a, "lt", &[&b]) } }
pub fn le<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Bool(num_v(&a) <= num_v(&b)) } else if let Some(o) = cmp_str(&a, &b) { Value::Bool(o.is_le()) } else { call_v(&a, "le", &[&b]) } }
pub fn gt<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Bool(num_v(&a) > num_v(&b)) } else if let Some(o) = cmp_str(&a, &b) { Value::Bool(o.is_gt()) } else { call_v(&a, "gt", &[&b]) } }
pub fn ge<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Bool(num_v(&a) >= num_v(&b)) } else if let Some(o) = cmp_str(&a, &b) { Value::Bool(o.is_ge()) } else { call_v(&a, "ge", &[&b]) } }
pub fn add<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value {
  let (a, b) = (a.cv(), b.cv());
  match &*a {
    Value::Num(x) => match &*b { Value::Num(y) => Value::Num(x + y), _ => Value::Num(x + num_v(&b)) },
    Value::Str(s) => { let mut out = String::with_capacity(s.len() + 8); out.push_str(s); out.push_str(&tos_v(&b)); Value::from(out) }
    x if arith(x) => Value::Num(num_v(x) + num_v(&b)),
    _ => call_v(&a, "plus", &[&b]),
  }
}
pub fn sub<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Num(num_v(&a) - num_v(&b)) } else { call_v(&a, "minus", &[&b]) } }
pub fn mul<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Num(num_v(&a) * num_v(&b)) } else { call_v(&a, "times", &[&b]) } }
pub fn div<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value {
  let (a, b) = (a.cv(), b.cv());
  if !arith(&a) { return call_v(&a, "over", &[&b]); }
  let (x, y) = (num_v(&a), num_v(&b));
  Value::Num(if y == 0.0 && x == 0.0 { 0.0 } else { x / y })
}
pub fn modulo<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Num(num_v(&a) % num_v(&b)) } else { call_v(&a, "mod", &[&b]) } }
pub fn neg<A: CV + ?Sized>(a: &A) -> Value { let a = a.cv(); if arith(&a) { Value::Num(-num_v(&a)) } else { get_v(&a, "negated") } }
pub fn power<A: CV + ?Sized, B: CV + ?Sized>(a: &A, b: &B) -> Value { let (a, b) = (a.cv(), b.cv()); if arith(&a) { Value::Num(num_v(&a).powf(num_v(&b))) } else { call_v(&a, "pow", &[&b]) } }
pub fn or_else<A: CV + ?Sized>(a: &A, b: impl FnOnce() -> Value) -> Value { let a = a.cv(); if a.is_null() { b() } else { a.into_owned() } }
pub fn assert_fail(says: &str) -> Value { panic!("assertion failed: {}", says) }

/// a number as the bootstrap writes it: whole numbers without a point, the exponent where JavaScript writes one
pub fn fmt_num(d: f64) -> String {
  if d.is_nan() { return "NaN".into(); }
  if d.is_infinite() { return if d > 0.0 { "Infinity".into() } else { "-Infinity".into() }; }
  if d == 0.0 { return "0".into(); }
  let a = d.abs();
  if a >= 1e21 || a < 1e-6 {
    let s = format!("{:e}", d);
    return match s.find('e') { Some(i) if !s[i + 1..].starts_with('-') => format!("{}e+{}", &s[..i], &s[i + 1..]), _ => s };
  }
  format!("{}", d)
}
pub fn tos<T: CV + ?Sized>(x: &T) -> String { tos_v(&x.cv()) }
pub fn tos_v(x: &Value) -> String {
  match x {
    Null => "null".into(),
    Value::Num(d) => fmt_num(*d),
    Value::Bool(b) => b.to_string(),
    Value::Str(s) => s.to_string(),
    Value::List(l) => l.borrow().iter().map(tos_v).collect::<Vec<_>>().join(","),
    Value::Obj(o) => { if o.cls.find_method("toString").is_some() { tos_v(&call_v(x, "toString", &[])) } else { o.cls.name.clone() } }
    Value::Fn(_) => "[program]".into(),
    Value::Cls(c) => c.name.clone(),
    Value::Many(m) => m.iter().map(tos_v).collect::<Vec<_>>().join(","),
    Value::Kw(k) => format!("{}: {}", k.0, tos_v(&k.1)),
  }
}

// --- lists and text ------------------------------------------------------------------------------------------
/// the items of a list, a superposition or a text (one a character), as a list of their own
pub fn items<T: CV + ?Sized>(xs: &T) -> Vec<Value> { items_v(&xs.cv()) }
pub fn items_v(xs: &Value) -> Vec<Value> {
  match xs {
    Value::Many(m) => (**m).clone(),
    Value::List(l) => l.borrow().clone(),
    Value::Str(s) => s.chars().map(|c| Value::from(c.to_string())).collect(),
    Null => Vec::new(),
    _ => panic!("not a list: {}", tos_v(xs)),
  }
}
fn lst(xs: &Value) -> &Rc<RefCell<Vec<Value>>> { match xs { Value::List(l) => l, _ => panic!("not a list: {}", tos_v(xs)) } }
pub fn len<T: CV + ?Sized>(xs: &T) -> Value { len_v(&xs.cv()) }
fn len_v(xs: &Value) -> Value {
  match xs {
    Value::List(l) => Value::Num(l.borrow().len() as f64),
    Value::Str(s) => Value::Num(s.chars().count() as f64),
    Value::Many(m) => Value::Num(m.len() as f64),
    _ => get_v(xs, "length"),
  }
}
fn index(i: f64, n: usize) -> Option<usize> { let mut i = i as i64; if i < 0 { i += n as i64; } if i >= 0 && (i as usize) < n { Some(i as usize) } else { None } }
pub fn elem<T: CV + ?Sized, K: CV + ?Sized>(t: &T, k: &K) -> Value { elem_v(&t.cv(), &k.cv()) }
fn elem_v(t: &Value, k: &Value) -> Value {
  match t {
    Value::List(l) => { let l = l.borrow(); index(num_v(k), l.len()).map(|i| l[i].clone()).unwrap_or(Null) }
    Null => Null,
    Value::Str(s) => { let cs: Vec<char> = s.chars().collect(); index(num_v(k), cs.len()).map(|i| Value::from(cs[i].to_string())).unwrap_or(Null) }
    Value::Many(m) => collapse(m.iter().map(|x| elem_v(x, k)).collect()),
    Value::Obj(_) | Value::Cls(_) => get_v(t, &key(k)),
    _ => Null,
  }
}
fn key(k: &Value) -> String { match k { Value::Str(s) => s.to_string(), _ => tos_v(k) } }
pub fn set_at<T: CV + ?Sized, K: CV + ?Sized, V: CV + ?Sized>(t: &T, k: &K, v: &V) -> Value {
  let (t, k, v) = (t.cv(), k.cv(), own(v));
  if let Value::List(l) = &*t {
    let i = num_v(&k) as i64;
    let mut l = l.borrow_mut();
    let i = if i < 0 { i + l.len() as i64 } else { i };
    if i < 0 { return v; }
    let i = i as usize;
    while l.len() <= i { l.push(Null); }
    l[i] = v.clone();
    return v;
  }
  set_v(&t, &key(&k), v.clone());
  v
}
pub fn push<T: CV + ?Sized, X: CV + ?Sized>(xs: &T, x: &X) -> Value { let xs = xs.cv(); let x = own(x); lst(&xs).borrow_mut().push(x); xs.into_owned() }
pub fn filt<T: CV + ?Sized, F: CV + ?Sized>(xs: &T, f: &F) -> Value {
  let (xs, f) = (xs.cv(), f.cv());
  let out: Vec<Value> = items_v(&xs).into_iter().filter(|x| truthy_v(&invoke(&*f, &[x]))).collect();
  if let Value::Many(_) = &*xs { Value::Many(Rc::new(out)) } else { Value::list(out) }
}
pub fn rng<T: CV + ?Sized>(n: &T) -> Value { let k = num(n) as i64; Value::list((0..k.max(0)).map(|i| Value::Num(i as f64)).collect()) }
pub fn filled<T: CV + ?Sized, V: CV + ?Sized>(n: &T, v: &V) -> Value { let k = num(n) as i64; let v = own(v); Value::list((0..k.max(0)).map(|_| v.clone()).collect()) }
fn contains_v(xs: &Value, x: &Value) -> bool { if let Value::Str(s) = xs { return s.contains(&*tos_v(x)); } items_v(xs).iter().any(|y| eq_v(y, x)) }
fn index_of_v(xs: &Value, x: &Value) -> Value {
  if let Value::Str(s) = xs { return match s.find(&*tos_v(x)) { Some(b) => Value::Num(s[..b].chars().count() as f64), None => Null }; }
  match items_v(xs).iter().position(|y| eq_v(y, x)) { Some(i) => Value::Num(i as f64), None => Null }
}
fn first_v(xs: &Value) -> Value { if let Value::Str(s) = xs { return s.chars().next().map(|c| Value::from(c.to_string())).unwrap_or(Null); } items_v(xs).into_iter().next().unwrap_or(Null) }
fn last_v(xs: &Value) -> Value { if let Value::Str(s) = xs { return s.chars().last().map(|c| Value::from(c.to_string())).unwrap_or(Null); } items_v(xs).pop().unwrap_or(Null) }
fn join_v(xs: &Value, sep: &Value) -> Value { let sep = tos_v(sep); Value::from(items_v(xs).iter().map(tos_v).collect::<Vec<_>>().join(&sep)) }
pub fn quoted<T: CV + ?Sized>(x: &T) -> Value {
  let s = tos(x);
  let mut out = String::from("\"");
  for c in s.chars() {
    match c { '"' => out.push_str("\\\""), '\\' => out.push_str("\\\\"), '\n' => out.push_str("\\n"), '\r' => out.push_str("\\r"), '\t' => out.push_str("\\t"),
      c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)), c => out.push(c) }
  }
  out.push('"');
  Value::from(out)
}
fn most_v(xs: &Value, key: &Value) -> Value {
  let l = items_v(xs);
  let (mut best, mut at, mut bk) = (None, 0usize, f64::NEG_INFINITY);
  for (i, x) in l.iter().enumerate() { let k = num_v(&invoke(key, &[x])); if best.is_none() || k > bk { best = Some(x.clone()); at = i; bk = k; } }
  match best { Some(b) => Value::list(vec![b, Value::Num(at as f64)]), None => Null }
}
fn sorted_by_v(xs: &Value, key: &Value) -> Value {
  let l = items_v(xs);
  let mut keyed: Vec<(f64, usize)> = l.iter().enumerate().map(|(i, x)| (num_v(&invoke(key, &[x])), i)).collect();
  keyed.sort_by(|p, q| p.0.total_cmp(&q.0).then(p.1.cmp(&q.1)));
  Value::list(keyed.into_iter().map(|(_, i)| l[i].clone()).collect())
}
fn summed(xs: &Value) -> Value { Value::Num(items_v(xs).iter().map(num_v).sum()) }
pub fn fail_with<T: CV + ?Sized>(says: &T) -> Value { panic!("{}", tos(says)) }
/// `fail` as a value, for a call the emitter could not tell from any other (`invoke(&fail, args![...])`)
#[allow(non_camel_case_types)]
#[derive(Clone, Copy)]
pub struct fail;
impl CV for fail { fn cv(&self) -> Cow<'_, Value> { Cow::Owned(fnv(|a: &[&Value]| fail_with(&arg(a, 0)))) } }
pub fn codepoints<T: CV + ?Sized>(s: &T) -> Value { Value::list(tos(s).chars().map(|c| Value::Num(c as u32 as f64)).collect()) }
pub fn from_codepoints<T: CV + ?Sized>(xs: &T) -> Value { Value::from(items(xs).iter().filter_map(|c| char::from_u32(num_v(c) as u32)).collect::<String>()) }
pub fn blank<T: CV + ?Sized>(c: &T) -> Value { let d = num(c); Value::Bool(d == 32.0 || d == 9.0 || d == 10.0 || d == 13.0) }
pub fn number<T: CV + ?Sized>(s: &T) -> Value {
  let t = tos(s); let t = t.trim();
  Value::Num(match t { "Infinity" | "+Infinity" => f64::INFINITY, "-Infinity" => f64::NEG_INFINITY, _ => t.parse::<f64>().unwrap_or(f64::NAN) })
}

// --- a member Ray knows on a list, a text or a number - and any object's own member of that name otherwise ---------
fn core(x: &Value) -> bool { matches!(x, Null | Value::List(_) | Value::Str(_) | Value::Num(_) | Value::Bool(_) | Value::Many(_)) }
macro_rules! member0 {
  ($name:ident, $member:expr, |$x:ident| $body:expr) => {
    pub fn $name<T: CV + ?Sized>(xs: &T) -> Value { let $x = xs.cv(); let $x: &Value = &$x; if core($x) { $body } else { get_v($x, $member) } }
  };
}
/* a member with arguments takes them as a slice (`m_split(&xs, args![sep])`): on any other object it is its own
 * member of that name, with however many arguments it was given (`Expr.split(e, name)`) */
macro_rules! member1 {
  ($name:ident, $member:expr, |$x:ident, $a:ident| $body:expr) => {
    pub fn $name<T: CV + ?Sized>(xs: &T, args: &[&Value]) -> Value { let $x = xs.cv(); let $x: &Value = &$x; if core($x) { let $a = arg(args, 0); let $a: &Value = &$a; $body } else { call_v($x, $member, args) } }
  };
}
macro_rules! member2 {
  ($name:ident, $member:expr, |$x:ident, $a:ident, $b:ident| $body:expr) => {
    pub fn $name<T: CV + ?Sized>(xs: &T, args: &[&Value]) -> Value { let $x = xs.cv(); let $x: &Value = &$x; if core($x) { let $a = arg(args, 0); let $a: &Value = &$a; let $b = arg(args, 1); let $b: &Value = &$b; $body } else { call_v($x, $member, args) } }
  };
}
fn st(x: &Value) -> String { tos_v(x) }
member1!(m_push, "push", |xs, x| { lst(xs).borrow_mut().push(x.clone()); xs.clone() });
member0!(m_chars, "chars", |xs| if let Value::Str(_) = xs { codepoints(xs) } else { get_v(xs, "chars") });
member0!(m_pop, "pop", |xs| lst(xs).borrow_mut().pop().unwrap_or(Null));
member1!(m_map, "map", |xs, f| Value::list(items_v(xs).iter().map(|x| invoke(f, &[x])).collect()));
member1!(m_for, "for", |xs, f| { for x in items_v(xs) { invoke(f, &[&x]); } Null });
member1!(m_some, "some", |xs, f| Value::Bool(items_v(xs).iter().any(|x| truthy_v(&invoke(f, &[x])))));
member1!(m_every, "every", |xs, f| Value::Bool(items_v(xs).iter().all(|x| truthy_v(&invoke(f, &[x])))));
member2!(m_reduce, "reduce", |xs, z, f| { let mut acc = z.clone(); for x in items_v(xs) { acc = invoke(f, &[&acc, &x]); } acc });
member1!(m_starts_with, "starts_with", |xs, a| Value::Bool(st(xs).starts_with(&*st(a))));
member1!(m_ends_with, "ends_with", |xs, a| Value::Bool(st(xs).ends_with(&*st(a))));
member2!(m_replace, "replace", |xs, a, b| Value::from(st(xs).replace(&*st(a), &st(b))));
member1!(m_split, "split", |xs, a| {
  let (s, sep) = (st(xs), st(a));
  if sep.is_empty() { Value::list(s.chars().map(|c| Value::from(c.to_string())).collect()) } else { Value::list(s.split(&*sep).map(Value::from).collect()) }
});
member0!(m_trim, "trim", |xs| Value::from(st(xs).trim()));
member0!(m_upper, "upper", |xs| Value::from(st(xs).to_uppercase()));
member0!(m_lower, "lower", |xs| Value::from(st(xs).to_lowercase()));
member0!(m_lines, "lines", |xs| Value::list(st(xs).split('\n').map(Value::from).collect()));
member1!(m_contains, "contains", |xs, a| Value::Bool(contains_v(xs, a)));
member1!(m_index_of, "index_of", |xs, a| index_of_v(xs, a));
member1!(m_join, "join", |xs, a| join_v(xs, a));
member0!(m_first, "first", |xs| first_v(xs));
member0!(m_last, "last", |xs| last_v(xs));
member0!(m_empty, "empty", |xs| Value::Bool(num_v(&len_v(xs)) == 0.0));
member1!(m_take, "take", |xs, a| {
  let n = num_v(a).max(0.0) as usize;
  if let Value::Str(s) = xs { Value::from(s.chars().take(n).collect::<String>()) } else { Value::list(items_v(xs).into_iter().take(n).collect()) }
});
member1!(m_drop, "drop", |xs, a| {
  let n = num_v(a).max(0.0) as usize;
  if let Value::Str(s) = xs { Value::from(s.chars().skip(n).collect::<String>()) } else { Value::list(items_v(xs).into_iter().skip(n).collect()) }
});
member0!(m_rest, "rest", |xs| m_drop(xs, &[&Value::Num(1.0)]));
member1!(m_concat, "concat", |xs, a| {
  if let Value::Str(s) = xs { Value::from(format!("{}{}", s, st(a))) } else { let mut out = items_v(xs); out.extend(items_v(a)); Value::list(out) }
});
member0!(m_reverse, "reverse", |xs| if let Value::Str(s) = xs { Value::from(s.chars().rev().collect::<String>()) } else { let mut out = items_v(xs); out.reverse(); Value::list(out) });
member0!(m_sum, "sum", |xs| summed(xs));
member1!(m_most, "most", |xs, f| most_v(xs, f));
member1!(m_sorted_by, "sorted_by", |xs, f| sorted_by_v(xs, f));
member0!(m_each, "each", |xs| Value::Many(Rc::new(items_v(xs))));
macro_rules! math0 {
  ($name:ident, $member:expr, |$d:ident| $body:expr) => {
    pub fn $name<T: CV + ?Sized>(x: &T) -> Value { let x = x.cv(); if arith(&x) { let $d = num_v(&x); Value::Num($body) } else { get_v(&x, $member) } }
  };
}
math0!(m_sqrt, "sqrt", |d| d.sqrt());
math0!(m_floor, "floor", |d| d.floor());
math0!(m_abs, "abs", |d| d.abs());
math0!(m_magnitude, "magnitude", |d| d.abs());
math0!(m_cos, "cos", |d| d.cos());
math0!(m_sin, "sin", |d| d.sin());
math0!(m_round, "round", |d| (d + 0.5).floor());
math0!(m_ln, "ln", |d| d.ln());
math0!(m_exp, "exp", |d| d.exp());
pub fn m_atan2<T: CV + ?Sized>(x: &T, a: &[&Value]) -> Value { let x = x.cv(); if arith(&x) { Value::Num(num_v(&x).atan2(num_v(&arg(a, 0)))) } else { call_v(&x, "atan2", a) } }
pub fn m_pow<T: CV + ?Sized>(x: &T, a: &[&Value]) -> Value { let x = x.cv(); if arith(&x) { Value::Num(num_v(&x).powf(num_v(&arg(a, 0)))) } else { call_v(&x, "pow", a) } }

// --- the Many: a superposition; members apply elementwise, equal things collapse ---------------------------------
pub fn many<T: CV + ?Sized>(xs: &T) -> Value { Value::Many(Rc::new(items(xs))) }
pub fn collapse(items: Vec<Value>) -> Value {
  if items.is_empty() { return Value::Many(Rc::new(items)); }
  let f = &items[0];
  if items.iter().all(|i| same(i, f)) { return f.clone(); }
  Value::Many(Rc::new(items))
}
